<script>
function printSuratJalan(){window.print();}
const serialData=<?=json_encode(array_reduce($items,function($carry,$it)use($serialMap){$carry[(string)$it['id']]=array_values(array_filter($serialMap[(int)$it['id']]??[],fn($s)=>$s['status']==='IN_TRANSIT'));return $carry;},[]),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let active=null;let sel=new Set();
function listFor(id){return (serialData[String(id)]||[]).map(x=>x.serial_number);}
function openReceive(id){active=String(id);sel=new Set();const input=document.getElementById('sn-'+id);if(input&&input.value)sel=new Set(input.value.split(/\n+/).filter(Boolean));const qty=parseInt(document.querySelector(`[data-row="${id}"] .receive-qty`).value||'0',10);document.getElementById('rmHint').textContent=`Pilih tepat ${qty} nomor seri yang benar-benar tiba.`;document.getElementById('rmSearch').value='';document.getElementById('receiveModal').classList.remove('hidden');document.getElementById('receiveModal').classList.add('flex');renderReceive();}
function closeReceive(){const m=document.getElementById('receiveModal');m.classList.add('hidden');m.classList.remove('flex');active=null;}
function renderReceive(){if(active===null)return;const qty=parseInt(document.querySelector(`[data-row="${active}"] .receive-qty`).value||'0',10);const term=document.getElementById('rmSearch').value.toLowerCase();const arr=listFor(active).filter(x=>x.toLowerCase().includes(term));document.getElementById('rmList').innerHTML=arr.map(sn=>`<label class="mb-2 flex items-center gap-3 rounded-xl border p-3 cursor-pointer"><input type="checkbox" ${sel.has(sn)?'checked':''} onchange="toggleR('${String(sn).replace(/'/g,"\\'")}',this)"><span class="font-mono text-sm">${esc(sn)}</span></label>`).join('')||'<div class="p-8 text-center text-sm text-gray-500">Nomor seri tidak ditemukan.</div>';}
function toggleR(sn,el){const qty=parseInt(document.querySelector(`[data-row="${active}"] .receive-qty`).value||'0',10);if(el.checked){if(sel.size>=qty){el.checked=false;return;}sel.add(sn);}else sel.delete(sn);}
function applyReceive(){const qty=parseInt(document.querySelector(`[data-row="${active}"] .receive-qty`).value||'0',10);if(sel.size!==qty){showError(`Pilih tepat ${qty} nomor seri.`);return;}document.getElementById('sn-'+active).value=[...sel].join('\n');document.querySelector('.serial-summary-'+active).textContent=`${sel.size} nomor seri dipilih`;closeReceive();}
function autoReceive(id){const qty=parseInt(document.querySelector(`[data-row="${id}"] .receive-qty`).value||'0',10);const a=listFor(id);const set=a.slice(0,qty);document.getElementById('sn-'+id).value=set.join('\n');document.querySelector('.serial-summary-'+id).textContent=`${set.length} nomor seri dipilih`;}
function acceptAll(){document.querySelectorAll('[data-row]').forEach(r=>{const id=r.dataset.row;const rem=parseInt(r.dataset.remaining||'0',10);const q=r.querySelector('.receive-qty');if(q)q.value=rem;if(r.dataset.serialized==='1')autoReceive(id);});}
function showError(msg){if(window.AppToast)AppToast.error(msg,'Penerimaan belum lengkap');else console.error(msg);}
function esc(v){return String(v).replace(/[&<>\\\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]||c));}
document.getElementById('rmSearch').addEventListener('input',renderReceive);
document.getElementById('receiveForm')?.addEventListener('submit',e=>{let ok=true;document.querySelectorAll('[data-row]').forEach(r=>{const q=parseInt(r.querySelector('.receive-qty')?.value||'0',10);if(q>0&&r.dataset.serialized==='1'){const sns=(document.getElementById('sn-'+r.dataset.row)?.value||'').split(/\n+/).filter(Boolean);if(sns.length!==q)ok=false;}});if(!ok){e.preventDefault();showError('Lengkapi jumlah dan nomor seri sesuai barang yang benar-benar diterima.');}});
</script>
<?php $content=ob_get_clean(); require __DIR__.'/../../layouts/app.php'; ?>
